excellences.schema:
// meaningalignment/excellences: the MAI roles document, in layered USL
// (plan 003). Leads were a `person` collection with a portrait; now they are
// Story accounts, and portraits come from their profiles.

main model Excellence {
  name       Text
  assessment Assessment
  leads      Person[]   // cross-reference
  projects   Project[]  // cross-reference
}

model Project {
  name        Text
  excellences Excellence[]  // cross-reference
}

Excellence.leads[] <-> Person.excellences[]
Excellence.projects[] <-> Project.excellences[]
Excellence.assessment <-> Assessment.excellences[]

enum Assessment { Good, Improving, Bad, "Current focus", "Not recorded" }

re Excellence {
  ~views([
    { label: "By project", line: [name, leads ~label("lead"), assessment ~bullet, projects ~summary ~label("project")], group: projects },
    { label: "By lead", group: leads },
    { label: "By assessment", group: assessment },
  ])
}

re Assessment {
  Good            ~color("#27815a")
  Improving       ~color("#bd861a")
  Bad             ~color("#c25357")
  "Current focus" ~color("#4278c0")
  "Not recorded"  ~color("#9aa0aa")
}

tasks.schema:
// No ~views: the default arrangement. Tasks keep their order within a project.
model Task {
  title   Text
  notes   Markdown?
  points  Int?
  done    Bool
  owner   Person?
  project Project?
  labels  Text[]
}

model Project {
  name  Text
  color Text? ~color
}

ordered Project.tasks[] <-> Task.project?
Task.owner? <-> Person.tasks[]

sorted.schema:
// Members listed by a field of theirs (`~sort`) instead of the order
// they were connected in.

model Game {
  name    Text
  authors Person[]
  tags    Tag[]

  ~views([
    { label: "Games",  line: [name, authors ~sort(name), tags ~sort(name)] },
    { label: "By tag", group: tags ~sort(name) },
  ])
}

model Tag {
  name Text
}

Game.authors[] @fold <-> Person.games[]
Game.tags[] @fold <-> Tag.games[]

directory.schema:
model Tie {
  person Person
  group  Person?
  kind   TieKind
}
enum TieKind { Community, Group, Shared, Opened }
Tie.person <-> Person.ties[]
Tie.group? <-> Person.members[]
Tie.kind <-> TieKind.ties[]

model Tree {
  title Text?
  owner Person?
}
model Visit {
  tree Tree
  at   Date
}
Tree.owner? <-> Person.trees[]
Visit.tree <-> Tree.visits[]

re Person {
  ~views([
    { label: "By group", group: ties.group, line: [name] },
    { label: "Everyone", line: [name, ties.group, ties.kind, ties ~count], sort: name },
  ])
}
re Tie {
  ~views([
    { label: "People", rows: person, line: [person, group, kind] },
  ])
}
re Tree {
  ~views([
    { label: "Recent", line: [title, owner, visits.at ~latest ~ago], sort: visits.at ~latest },
  ])
}
